def btn(label,url,secondary=False,external=False):return f'<a class="btn{" secondary" if secondary else ""}" href="{url}"'+(' target="_blank" rel="noopener noreferrer"' if external else '')+f'>{label}</a>'
def page(slug,title,desc,body):
    filename='index.html' if slug=='index' else slug+'.html';pages.append(filename)
    (R/filename).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{html.escape(title)} | STR Booster</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta property="og:title" content="{html.escape(title,quote=True)} | STR Booster"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:type" content="website"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,400;0,500;1,400&family=Outfit:wght@400;500;600;700&display=swap"><link rel="stylesheet" href="/styles.css"><script src="/app.js" defer></script><script async src="https://www.googletagmanager.com/gtag/js?id=G-YQ9L9GHV31"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){{dataLayer.push(arguments);}}gtag("js",new Date());gtag("config","G-YQ9L9GHV31");</script></head><body>{header}<main id="main">{body}</main>{footer}</body></html>'''.replace('><','>\n<'))
def hero(label,title,copy,actions=''):
    return f'<section class="page-hero"><div class="wrap"><div class="breadcrumb"><a href="/">Home</a> / {label}</div><p class="eyebrow">{label}</p><h1>{title}</h1><p class="lead">{copy}</p>{actions}</div></section>'
def section(content,cls='',id=''):return f'<section class="section {cls}"'+(f' id="{id}"' if id else '')+f'><div class="wrap">{content}</div></section>'
def intro(label,title,copy=''):return f'<div class="intro"><p class="eyebrow">{label}</p><h2>{title}</h2>'+ (f'<p>{copy}</p>' if copy else '')+'</div>'
def card(title,copy,url,label='Explore',number='',extra=''):return f'<article class="card">'+(f'<span class="number">{number}</span>' if number else '')+f'<h3>{title}</h3><p>{copy}</p>{extra}<a class="text-link" href="{url}">{label} →</a></article>'
def services_grid():return '<div class="grid two">'+''.join(card(s[1],s[2],'/'+s[0]+'.html','Explore service',f'0{i+1}') for i,s in enumerate(services))+'</div>'
def app_cards():return '''<div class="grid two"><article class="card app-card"><p class="eyebrow">Guest intelligence</p><h3>Guest Intel</h3><p>Understand who your rental serves best and turn that insight into clearer positioning and more relevant marketing.</p><a class="text-link" href="/guest-intel.html">Discover Guest Intel →</a></article><article class="card app-card"><p class="eyebrow">Revenue marketing</p><h3>52Rev <span class="badge">Beta</span></h3><p>Connect each week of the year with an ideal guest, a revenue opportunity and a marketing playbook.</p><a class="text-link" href="/52rev.html">Discover 52Rev →</a></article></div>'''
